getMove(roll):
  if asc>=17:
    if roll < 40:
      if lastTwoMoves == CORROSIVE_SPIT: return aiRng.randomBoolean(0.5) ? TACKLE : LICK
      else: return CORROSIVE_SPIT
    elif roll < 80:
      if lastTwoMoves == TACKLE: return aiRng.randomBoolean(0.5) ? CORROSIVE_SPIT : LICK
      else: return TACKLE
    elif lastMove == LICK: return aiRng.randomBoolean(0.4) ? CORROSIVE_SPIT : TACKLE
    else: return LICK
  else:
    if roll < 30:
      if lastTwoMoves == CORROSIVE_SPIT: return aiRng.randomBoolean(0.5) ? TACKLE : LICK
      else: return CORROSIVE_SPIT
    elif roll < 70:
      if lastMove == TACKLE: return aiRng.randomBoolean(0.4) ? CORROSIVE_SPIT : LICK
      else: return TACKLE
    elif lastTwoMoves == LICK: return aiRng.randomBoolean(0.4) ? CORROSIVE_SPIT : TACKLE
    else: return LICK
